from jose.exceptions import JWSError, JWTError, JOSEError


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(s: str) -> bytes:
    s = s + "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s.encode("ascii"))


def _make_jwe_compact(
    alg: str = "dir",
    enc: str = "A256GCM",
    zip_alg: str = "DEF",
    plaintext: bytes = b"hello world",
    key: bytes = b"\x00" * 32,
) -> str:
    """Build a minimal JWE compact serialization string.

    The ciphertext and tag are dummy values; the point is to exercise the
    decompression path in jwe.decrypt, not to produce a validly-encrypted
    token.
    """
    protected = {
        "alg": alg,
        "enc": enc,
    }
    if zip_alg:
        protected["zip"] = zip_alg

    protected_b64 = _b64url_encode(json.dumps(protected, separators=(",", ":")).encode())

    # Dummy ciphertext (16 bytes) + tag (16 bytes for GCM)
    ciphertext = b"\x00" * 16
    tag = b"\x00" * 16

    # If zip is set, the "ciphertext" field actually contains the compressed
    # payload.  We craft a zlib stream that decompresses to a large buffer.
    if zip_alg:
        # Create a highly compressible payload: 1 MB of zeros
        large_payload = b"\x00" * (1024 * 1024)
        compressed = zlib.compress(large_payload, level=9)
        ciphertext = compressed
        tag = b"\x00" * 16

    # JWE compact: header . encrypted_key . iv . ciphertext . tag
    # For "dir" algorithm, encrypted_key is empty.
    parts = [
        protected_b64,
        "",  # empty encrypted key for dir
        _b64url_encode(b"\x00" * 12),  # 12-byte IV
        _b64url_encode(ciphertext),
        _b64url_encode(tag),
    ]
    return ".".join(parts)


def _make_ssh_ecdsa_key() -> bytes:
    """Create a minimal OpenSSH-format ECDSA key blob.

    OpenSSH key format:
      4-byte length + "ssh-ed25519" (or "ecdsa-sha2-nistp256", etc.)
      4-byte length + curve name
      4-byte length + point (Q)
      4-byte length + private key (d)
    """
    def _put_str(b: bytes) -> bytes:
        return struct.pack(">I", len(b)) + b

    key_type = b"ecdsa-sha2-nistp256"
    curve = b"nistp256"
    # Dummy 65-byte uncompressed point (0x04 || 32-byte X || 32-byte Y)
    point = b"\x04" + b"\x01" * 32 + b"\x02" * 32
    # Dummy 32-byte private key
    priv = b"\x03" * 32

    blob = _put_str(key_type) + _put_str(curve) + _put_str(point) + _put_str(priv)
    return blob


# ---------------------------------------------------------------------------
# GHSA-6c5p-j8vq-pqhj  (CVE-2024-33663) – algorithm confusion with OpenSSH ECDSA keys
# ---------------------------------------------------------------------------

def test_ghsa_6c5p_j8vq_pqhj_fix_pinning():
    """jws.verify must reject an OpenSSH ECDSA key used with an ECDSA algorithm (no algorithm confusion)."""
    ssh_key = _make_ssh_ecdsa_key()
    # Sign a token with a normal EC key first to get a valid JWS structure,
    # then attempt verification with the SSH key.
    # Actually, the vulnerability is that python-jose 3.3.0 would accept an
    # OpenSSH ECDSA key as if it were a standard EC key.  We craft a JWS
    # token and try to verify it with the SSH key.
    #
    # The simplest trigger: call jws.verify with an SSH key and an ECDSA
    # algorithm.  In 3.3.0 the key is parsed as a valid EC key (algorithm
    # confusion); in 3.4.0 it should raise an error.
    #
    # We need a token that was signed with a *different* key so the signature
    # check would fail anyway, but the key-parsing step is what we're testing.
    # Use a valid EC key to sign, then verify with the SSH key.
    from jose.jwk import construct
    # Generate a valid EC P-256 key for signing
    ec_key = construct(
        {
            "kty": "EC",
            "crv": "P-256",
            "x": "M111111111111111111111111111111111111111111",
            "y": "M222222222222222222222222222222222222222222",
            "d": "M333333333333333333333333333333333333333333",
        },
        algorithm=Algorithms.ES256,
    )
    token = jws.sign(b"payload", ec_key, algorithm=Algorithms.ES256)

    # Attempt to verify with the SSH key – should raise in 3.4.0
    with pytest.raises((JWSError, JOSEError, Exception)):
        jws.verify(token, ssh_key, algorithms=[Algorithms.ES256])


def test_ghsa_6c5p_j8vq_pqhj_exposure():
    """Application call pattern: jwt.decode with an SSH ECDSA key must not succeed (algorithm confusion)."""
    ssh_key = _make_ssh_ecdsa_key()
    # The application calls jwt.decode(token, key, algorithms=[alg]).
    # Craft a token signed with a valid EC key, then decode with the SSH key.
    from jose.jwk import construct
    ec_key = construct(
        {
            "kty": "EC",
            "crv": "P-256",
            "x": "M11111111111111111111111111111111111111111",
            "y": "M222222222222222222222222222222222222222222",
            "d": "M333333333333333333333333333333333333333333",
        },
        algorithm=Algorithms.ES256,
    )
    token = jwt.encode({"sub": "test"}, ec_key, algorithm=Algorithms.ES256)

    # Application pattern: jwt.decode(token, key, algorithms=[alg])
    with pytest.raises((JWTError, JOSEError, Exception)):
        jwt.decode(token, ssh_key, algorithms=[Algorithms.ES256])


