# GHSA-cjwg-qfpm-7377  (CVE-2024-33664) – DoS via compressed JWE content (JWT bomb)
# ---------------------------------------------------------------------------

def test_ghsa_cjwg_qfpm_7377_fix_pinning():
    """jwe.decrypt must reject or limit decompression of a JWE with a high compression ratio (JWT bomb)."""
    # Craft a JWE with a "zip" header and a compressed payload that expands
    # to ~1 MB.  In 3.3.0 this would consume excessive memory; in 3.4.0 the
    # library should raise an error or limit the decompressed size.
    bomb_jwe = _make_jwe_compact(
        alg="dir",
        enc="A256GCM",
        zip_alg="DEF",
        plaintext=b"\x00" * (1024 * 1024),
        key=b"\x00" * 32,
    )
    key = b"\x00" * 32
    # In 3.4.0 this should raise an error (e.g., decompression limit exceeded)
    # rather than silently allocating a large buffer.
    with pytest.raises((JOSEError, Exception)):
        jwe.decrypt(bomb_jwe, key)


def test_ghsa_cjwg_qfpm_7377_exposure():
    """Application call pattern: jwe.decrypt with a crafted compressed JWE must not cause unbounded resource use."""
    # The application does not directly call jwe.decrypt in the listed call
    # sites, but the advisory affects jwe.decrypt.  We simulate the exposure
    # by calling jwe.decrypt with a bomb token, matching the public API.
    bomb_jwe = _make_jwe_compact(
        alg="dir",
        enc="A256GCM",
        zip_alg="DEF",
        plaintext=b"\x00" * (1024 * 1024),
        key=b"\x00" * 32,
    )
    key = b"\x00" * 32
    with pytest.raises((JOSEError, Exception)):
        jwe.decrypt(bomb_jwe, key)


